    export const getListInsightFactsUrl = (projectId: string,
    params?: ListInsightFactsParams,) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {

    if (value !== undefined) {
      normalizedParams.append(key, value === null ? 'null' : String(value))
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0 ? `/api/projects/${projectId}/insight-facts?${stringifiedParams}` : `/api/projects/${projectId}/insight-facts`
}

